    { id: 'eRadet', mal: 122, akt: 8, titel: 'Låt rådet styra', plats: 'stockholm', ar: 1567, man: 10, slag: 'beslut', kostar: { mark: 48000000 }, ger: {  }, mer: 'Kungen är sjuk. Han ber Gud och människor om förlåtelse och ber biskoparna låta folket be för riket.', merKalla: 'sv. Wikipedia, Sturemorden',
      kronika: 'Rådet styr riket. Johan släpps fri från Gripsholm i oktober, och Jöran Persson döms till döden men avrättas inte.' },
    { id: 'eGetaryggen', mal: 129, akt: 8, titel: 'Stoppa Rantzau vid Getaryggen', plats: 'getaryggen', ar: 1567, man: 10.95, slag: 'tag', strid: 'nederlag', kostar: { man: 2000, mark: 53000000 }, ger: {  }, folk: [50, 45], egen: 'Peder Siöblads män', fiende: 'Danskarna', order: [{ vanta: 4, ord: 'Vänta', rad: 'Vid Getaryggen väster om Jönköping står ett blockhus som kungen själv har ritat. Peder Siöblad har nära 2 000 man där.' }, { ord: 'Håll<br>blockhuset', mal: 'egen', rad: 'Danskarnas fotfolk klättrar uppför backen.', bra: 'Skyttarna håller dem borta.', miss: 'Danskarna kommer närmare.' }, { hugg: 1, ord: 'Skjut!', rad: 'Skyttarna skjuter från vallarna.', bra: 'Danskarna tvekar.', miss: 'Danskarna tar sig upp.' }, { ord: 'Håll<br>flanken', mal: 'flank', rad: 'Danskarnas ryttare rider runt på södra sidan.', alltid: 'Ryttarna bryter in i lägret. Svenskarna flyr.' }], mer: 'Medan kungen är sjuk tågar Daniel Rantzau från Halmstad upp längs Nissastigen med 8 500 man och 900 vagnar, in i Småland mot Jönköping.', merKalla: 'sv. Wikipedia, Slaget vid Getaryggen och Rantzaus räd i Småland och Östergötland',
      kronika: 'Vid Getaryggen bryter danskarna in i lägret. Svenskarna bränner själva Jönköping, och Rantzau tågar vidare in i Östergötland och bränner Vadstena. Slottet tar han inte.' },
    { id: 'eBrollop', mal: 136, akt: 8, scen: 'brollop', titel: 'Gift dig med Karin Månsdotter', plats: 'stockholm', ar: 1568, man: 7.1, slag: 'rid', kostar: { mark: 57000000 }, ger: {  }, mer: 'Kungen är frisk igen och har tagit tillbaka makten. Han och Karin Månsdotter har gift sig i hemlighet, och nu ska det ske inför alla. Hon är en knekts dotter.', merKalla: 'sv. Wikipedia, Karin Månsdotter',
      kronika: 'Karin Månsdotter gifts med kungen i Storkyrkan, och dagen efter kröns hon till drottning.' },
    { id: 'eUpproret', forlust: 1, mal: 144, akt: 8, titel: 'Håll Stockholm mot hertigarna', plats: 'stockholm', ar: 1568, man: 8.6, slag: 'beslut', belagring: 1, tid: 80, kostar: { mark: 58000000 }, ger: { slut: true }, egen: 'Stockholm', fiende: 'Hertigarnas här', order: [{ vanta: 5, ord: 'Vänta', rad: 'Hertigarna Johan och Karl har rest sig mot kungen. I mitten av september står deras här utanför Stockholm.' }, { bild: 'kanon', ord: 'Skjut!', hur: 'Tryck på ringen: slottets kanoner skjuter mot hertigarnas läger.', rad: 'Hertigarnas här ligger runt staden.', bra: 'Kanonerna håller dem på avstånd.', miss: 'Hertigarnas här kommer närmare.' }, { bild: 'mana', ord: 'Mana<br>knektarna', hur: 'Tryck på ringen: kungen manar knektarna på muren.', rad: 'Knektarna ropar över stadsmuren att Jöran Persson ska lämnas ut.', alltid: 'Knektarna tvingar fram att Jöran Persson lämnas ut till hertigarna. Den 22 september avrättas han på Brunkeberg.' }, { hugg: 1, bild: 'kanon', ord: 'Skjut!', rad: 'Belägringen fortsätter.', bra: 'Kanonerna svarar från slottet.', miss: 'Det blir tyst på murarna.' }, { vanta: 5, ord: 'Vänta', rad: 'Staden kan inte hålla ut längre.' }], mer: 'Johan och Karl har gjort upp med en del av adeln, och i juli reser de sig mot kungen.', merKalla: 'sv. Wikipedia, Johan III och Jöran Persson',
      kronika: 'Den 29 september öppnas Stockholms portar för hertigarna. Erik tas till fånga, och Johan hyllas som kung.',
      vet: 'Erik sitter fången. Johan låter vakta honom noga.' }
